with with_windows as (select *, sum(rating) over w_part as country_sum_rating, first_value(rating, true) over (order by rating, id rows between unbounded preceding and current row) as first_known_rating from suppliers window w_part as (partition by country, city)), with_last as (select s.*, latest.product_launch_date, latest.product_category from with_windows s join lateral (select c.launch_date as product_launch_date, c.category as product_category from products c where c.supplier_id = s.id order by c.cost desc, c.id desc limit 1) latest on true), matched_keys as (select city from with_last intersect all select city from suppliers where rating between 2.7 and 3.7), verified as (select s.* from with_last s inner join matched_keys k on s.city = k.city), scored as (select *, cume_dist() over (partition by city order by country_sum_rating nulls first) as country_sum_rating_cume_dist, rank() over w_hist as first_known_rating_rank, percent_rank() over (partition by product_category, city order by country_sum_rating nulls last) as country_sum_rating_percent_rank from verified window w_hist as (order by first_known_rating desc nulls last)), eligible as (select s.* from scored s where exists (select 1 from products c where c.supplier_id = s.id and c.launch_date <= s.product_launch_date)), enriched as (select *, round(rating / sum(rating) over (partition by country, product_category), 4) as rating_share, sum(first_known_rating_rank) over (partition by country) as country_sum_first_known_rating_rank from eligible) select id, supplier_name, country, city, rating, product_launch_date, product_category, country_sum_rating_cume_dist, first_known_rating_rank, case when city rlike '^(London|Chiang Mai)$' then 'OTHER_ZONE' when city rlike '^(Bangkok|New York)$' then 'CORE' else 'GROUP_A' end as city_zone from enriched;
